#version 450

layout(location = 0) in vec3 position;
layout(location = 1) in vec3 normal;
layout(location = 2) in vec2 uv;

layout(set = 0, binding = 0) uniform Camera {
    mat4 view;
    mat4 projection;
    vec3 camera_position;
};

layout(location = 0) out vec3 frag_pos;
layout(location = 1) out vec3 frag_normal;
layout(location = 2) out vec2 frag_uv;

void main() {
    frag_pos = position;
    frag_normal = normal;
    frag_uv = uv;
    gl_Position = projection * view * vec4(position, 1.0);
}

#version 450

layout(location = 0) in vec3 frag_pos;
layout(location = 1) in vec3 frag_normal;
layout(location = 2) in vec2 frag_uv;

layout(set = 0, binding = 0) uniform Camera {
    mat4 view;
    mat4 projection;
    vec3 camera_position;
};

layout(set = 1, binding = 0) uniform Material {
    vec4 base_color;
    float metallic;
    float roughness;
};

layout(set = 2, binding = 0) uniform Light {
    vec3 direction;
    float _pad1;
    vec3 color;
    float intensity;
};

layout(location = 0) out vec4 out_color;

void main() {
    vec3 N = normalize(frag_normal);
    vec3 L = normalize(-direction);
    vec3 V = normalize(camera_position - frag_pos);

    // Diffuse
    float diffuse = max(dot(N, L), 0.0);

    // Specular (Phong)
    vec3 R = reflect(-L, N);
    float shininess = mix(128.0, 1.0, roughness);
    float spec = pow(max(dot(R, V), 0.0), shininess);

    vec3 ambient = base_color.rgb * 0.1;
    vec3 diffuse_color = base_color.rgb * color * diffuse * intensity;
    vec3 spec_color = color * spec * intensity * (1.0 - roughness);

    out_color = vec4(ambient + diffuse_color + spec_color, base_color.a);
}
